const payload = JSON.parse($input.first().json.payload);
function chunkStructural(text, target) {
  const sentences = text.split(/(?<=[.!?])\s+/);
  const chunks = []; let pos = 0, curStart = 0, curText = '';
  for (const sent of sentences) {
    let idx = text.indexOf(sent, pos); if (idx === -1) idx = pos;
    const sStart = idx, sEnd = idx + sent.length;
    if (curText && (curText.length + sent.length + 1 > target)) {
      chunks.push({start: curStart, end: pos, text: curText});
      curText = sent; curStart = sStart;
    } else {
      if (!curText) curStart = sStart;
      curText = curText ? (curText + ' ' + sent).trim() : sent;
    }
    pos = sEnd;
  }
  if (curText) chunks.push({start: curStart, end: text.length, text: curText});
  return chunks;
}
const childSize = payload.chunk_size_child || 90;
const children = chunkStructural(payload.document, childSize);
return [{json: {
  question: payload.question,
  parent_text: payload.document,
  children: children,
  child_size: childSize
}}];

const d = $('Нарезка иерархическая: дети + родитель').first().json;
const resp = $input.first().json;
function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}
const vecs = resp.data.map(x => x.embedding);
const qVec = vecs[0];
const childVecs = vecs.slice(1);
let bestIdx = 0, bestSim = -1;
childVecs.forEach((v, i) => { const s = cosine(qVec, v); if (s > bestSim) { bestSim = s; bestIdx = i; } });
return [{json: {
  question: d.question,
  parent_text: d.parent_text,
  top1_child: d.children[bestIdx],
  top1_child_similarity: bestSim,
  n_children: d.children.length
}}];

const d = $input.first().json;
// единица поиска (top1_child) и единица ответа (parent_text) — не один и тот же объект;
// модель получает ВЕСЬ документ, не найденный мелкий кусочек.
return [{json: {
  question: d.question,
  found_child_text: d.top1_child.text,
  found_child_similarity: d.top1_child_similarity,
  context_for_answer: d.parent_text
}}];

