const d = $('Подстановка родителя').first().json;
const resp = $input.first().json;
let content = null; try { content = resp.choices[0].message.content; } catch(e) {}
return [{json: {
  question: d.question,
  found_child_text: d.found_child_text,
  model_answer: content
}}];

const hier = $input.first().json;
const payload = JSON.parse($('Документ + вопрос').first().json.payload);
function splitSentencesWithSpans(text) {
  const sentences = text.split(/(?<=[.!?])\s+/);
  const out = []; let pos = 0;
  for (const sent of sentences) {
    if (!sent.trim()) continue;
    let idx = text.indexOf(sent, pos); if (idx === -1) idx = pos;
    const sStart = idx, sEnd = idx + sent.length;
    out.push({start: sStart, end: sEnd, text: sent});
    pos = sEnd;
  }
  return out;
}
const sentences = splitSentencesWithSpans(payload.document);
return [{json: {
  question: hier.question,
  found_child_text: hier.found_child_text,
  model_answer: hier.model_answer,
  gap_threshold: (payload.gap_threshold !== undefined) ? payload.gap_threshold : 0.15,
  sentences: sentences
}}];

const d = $('Нарезка семантическая: предложения').first().json;
const resp = $input.first().json;
function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}
const vecs = resp.data.map(x => x.embedding);
const sentences = d.sentences;
const threshold = d.gap_threshold;
const gaps = [];
for (let i = 0; i < vecs.length - 1; i++) { gaps.push(1 - cosine(vecs[i], vecs[i+1])); }
const chunks = []; let curStart = sentences[0].start, curEnd = sentences[0].end, curN = 1;
for (let i = 0; i < sentences.length - 1; i++) {
  const gap = gaps[i];
  if (gap > threshold) {
    chunks.push({start: curStart, end: curEnd, n_sentences: curN, cut_after_gap: gap});
    curStart = sentences[i+1].start; curEnd = sentences[i+1].end; curN = 1;
  } else {
    curEnd = sentences[i+1].end; curN += 1;
  }
}
chunks.push({start: curStart, end: curEnd, n_sentences: curN, cut_after_gap: null});
return [{json: {
  question: d.question,
  found_child_text: d.found_child_text,
  model_answer: d.model_answer,
  gap_threshold: threshold,
  n_sentences: sentences.length,
  gaps: gaps.map(g => Math.round(g * 10000) / 10000),
  n_chunks: chunks.length,
  chunks: chunks
}}];
